import { useMemo } from 'react';
import { useIntl } from 'react-intl';
import { useLocation } from 'react-router-dom';

import { BasicContainer } from 'components';
import { FilterRegistry } from 'domain/Filter';
import { usePageFilterApplied } from 'hooks';

import {
  exploreFurtherBasicContainerBackground,
  StyledCardDescription,
  StyledCardFooter,
  StyledCardHeaderRow,
  StyledCardIcon,
  StyledCardTextColumn,
  StyledCardTitle,
  StyledCommercialResultsCard,
  StyledCommercialResultsInactiveShell,
  StyledCommercialResultsLink,
  StyledCommercialResultsLinkLabel,
  StyledExploreFurtherBody,
  StyledExploreFurtherCards,
  StyledExploreFurtherLinkArrow,
  StyledExploreFurtherRoot,
  StyledExploreFurtherSubtitle,
  StyledWatchTowerBody,
  StyledWatchTowerCard,
  StyledWatchTowerLinkLabel,
} from './ExploreFurther.styles';
import type { ExploreFurtherProps } from './types';

function locationSearchHasFilterParams(search: string): boolean {
  const qs = search.startsWith('?') ? search.slice(1) : search;
  if (!qs) {
    return false;
  }
  const params = new URLSearchParams(qs);
  for (const key of params.keys()) {
    if (key.startsWith('filter_')) {
      return true;
    }
  }
  return false;
}

export const ExploreFurther = ({
  filterPageName,
  commercialResultsPath,
}: ExploreFurtherProps) => {
  const { formatMessage } = useIntl();
  const location = useLocation();
  const { applied } = usePageFilterApplied(filterPageName);

  const commercialResultsHref = useMemo(() => {
    const sourceSearch = locationSearchHasFilterParams(location.search)
      ? location.search
      : FilterRegistry.buildFilterQueryString(applied);

    return FilterRegistry.mergeFilterParamsIntoHref(
      commercialResultsPath,
      sourceSearch,
    );
  }, [applied, commercialResultsPath, location.search]);

  const commercialResultsCard = (
    <StyledCommercialResultsCard
      interactive
      border="medium"
      elevated="minimal"
      data-testid="explore-further-commercial-results-card"
    >
      <StyledWatchTowerBody>
        <StyledCardHeaderRow>
          <StyledCardIcon tone="active" aria-hidden>
            CR
          </StyledCardIcon>
          <StyledCardTextColumn>
            <StyledCardTitle size="H5">
              {formatMessage({
                id: 'ExploreFurther.commercialResults.title',
              })}
            </StyledCardTitle>
            <StyledCardDescription>
              {formatMessage({
                id: 'ExploreFurther.commercialResults.description',
              })}
            </StyledCardDescription>
          </StyledCardTextColumn>
        </StyledCardHeaderRow>
        <StyledCardFooter>
          <StyledCommercialResultsLinkLabel>
            {formatMessage({
              id: 'ExploreFurther.commercialResults.linkLabel',
            })}
            <StyledExploreFurtherLinkArrow aria-hidden size="medium" />
          </StyledCommercialResultsLinkLabel>
        </StyledCardFooter>
      </StyledWatchTowerBody>
    </StyledCommercialResultsCard>
  );

  return (
    <StyledExploreFurtherRoot>
      <BasicContainer
        dataTestId="explore-further"
        layout={{
          bodyPadding: false,
          background: exploreFurtherBasicContainerBackground,
        }}
        header={{
          title: formatMessage({
            id: 'ExploreFurther.title',
          }),
          tooltip: {
            text: formatMessage({
              id: 'ExploreFurther.tooltip',
            }),
          },
        }}
      >
        <StyledExploreFurtherBody>
          <StyledExploreFurtherSubtitle data-testid="explore-further-subtitle">
            {formatMessage({
              id: 'ExploreFurther.subtitle',
            })}
          </StyledExploreFurtherSubtitle>
          <StyledExploreFurtherCards>
            <StyledCommercialResultsInactiveShell data-testid="explore-further-commercial-results-wrapper">
              <StyledCommercialResultsLink
                to={commercialResultsHref}
                data-testid="explore-further-commercial-results-link"
              >
                {commercialResultsCard}
              </StyledCommercialResultsLink>
            </StyledCommercialResultsInactiveShell>

            <StyledWatchTowerCard
              interactive={false}
              border="medium"
              elevated="minimal"
              aria-disabled={true}
              data-testid="explore-further-watchtower-card"
            >
              <StyledWatchTowerBody>
                <StyledCardHeaderRow>
                  <StyledCardIcon tone="muted" aria-hidden>
                    WT
                  </StyledCardIcon>
                  <StyledCardTextColumn>
                    <StyledCardTitle size="H5" muted>
                      {formatMessage({
                        id: 'ExploreFurther.watchTower.title',
                      })}
                    </StyledCardTitle>
                    <StyledCardDescription muted>
                      {formatMessage({
                        id: 'ExploreFurther.watchTower.description',
                      })}
                    </StyledCardDescription>
                  </StyledCardTextColumn>
                </StyledCardHeaderRow>
                <StyledCardFooter>
                  <StyledWatchTowerLinkLabel data-testid="explore-further-watchtower-link-label">
                    {formatMessage({
                      id: 'ExploreFurther.watchTower.linkLabel',
                    })}
                    <StyledExploreFurtherLinkArrow aria-hidden size="medium" />
                  </StyledWatchTowerLinkLabel>
                </StyledCardFooter>
              </StyledWatchTowerBody>
            </StyledWatchTowerCard>
          </StyledExploreFurtherCards>
        </StyledExploreFurtherBody>
      </BasicContainer>
    </StyledExploreFurtherRoot>
  );
};
